1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
22	    @Mapping(target = "initials", expression = "java(initials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    OwnerDto toOwnerDto(Owner owner);
29	
30	    /**
31	     * Derives the owner's preferred contact channel: {@code 'EMAIL'} when an email address
32	     * is present (non-null and non-blank), otherwise {@code 'PHONE'}.
33	     */
34	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
35	        if (owner == null) {
36	            return null;
37	        }
38	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
39	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
40	    }
41	
42	    /**
43	     * Derives the owner's locality from the region its identity carries (see
44	     * {@link #localityRegion(Owner)}). Returns that region string, or {@code 'UNKNOWN'} when the
45	     * owner has no known region.
46	     */
47	    default String locality(Owner owner) {
48	        if (owner == null) {
49	            return null;
50	        }
51	        String region = localityRegion(owner);
52	        return region != null ? region : "UNKNOWN";
53	    }
54	
55	    /**
56	     * Resolves the region an owner's {@link #locality(Owner)} is derived from. This is the
57	     * {@code REGION} segment carried by the owner's {@code customerCode}, whose new
58	     * {@code '<REGION>-<HASH8>'} identity encodes the region ahead of the first {@code '-'}. The
59	     * sentinel {@code 'UNKNOWN'} region (used when the owner has no known region) and a missing
60	     * customer code both resolve to {@code null}. Keeping the region source in its own method leaves
61	     * {@link #locality(Owner)} owning only the {@code null -> 'UNKNOWN'} rendering, so where the
62	     * region itself comes from can change without disturbing that rendering.
63	     *
64	     * @param owner the owner whose locality region is resolved, never {@code null}
65	     * @return the region string, or {@code null} when the owner has no known region
66	     */
67	    default String localityRegion(Owner owner) {
68	        String code = owner.getCustomerCode();
69	        if (code == null) {
70	            return null;
71	        }
72	        int dash = code.indexOf('-');
73	        String region = dash >= 0 ? code.substring(0, dash) : code;
74	        return "UNKNOWN".equals(region) ? null : region;
75	    }
76	
77	    /**
78	     * Returns the owner's numeric membership level, assigned on creation. The level starts at
79	     * {@code 1}, gains {@code 1} when an email is present, gains {@code 1} when the owner has no
80	     * namesakes (namesakeCount is 0), and is capped at {@code 3} (level 4 is reserved for tenure).
81	     */
82	    default Integer membershipLevel(Owner owner) {
83	        if (owner == null) {
84	            return null;
85	        }
86	        int level = 1;
87	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
88	        if (hasEmail) {
89	            level++;
90	        }
91	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
92	        if (noNamesakes) {
93	            level++;
94	        }
95	        return Math.min(level, 3);
96	    }
97	
98	    /**
99	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
100	     * last two digits of the registrationDate year, e.g. {@code 'NSW-A1B2C3D4-M26'}. Returns
101	     * {@code null} when the owner has no customer code or registration date.
102	     */
103	    default String membershipNumber(Owner owner) {
104	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
105	            return null;
106	        }
107	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
108	    }
109	
110	    /**
111	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits
112	     * contained in the owner's customerCode. Returns {@code null} when the owner has no
113	     * customer code.
114	     */
115	    default Integer checkDigit(Owner owner) {
116	        if (owner == null || owner.getCustomerCode() == null) {
117	            return null;
118	        }
119	        String code = owner.getCustomerCode();
120	        int sum = 0;
121	        boolean dbl = true;
122	        for (int i = code.length() - 1; i >= 0; i--) {
123	            char c = code.charAt(i);
124	            if (c < '0' || c > '9') {
125	                continue;
126	            }
127	            int d = c - '0';
128	            if (dbl) {
129	                d *= 2;
130	                if (d > 9) {
131	                    d -= 9;
132	                }
133	            }
134	            sum += d;
135	            dbl = !dbl;
136	        }
137	        return (10 - (sum % 10)) % 10;
138	    }
139	
140	    /**
141	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
142	     */
143	    default String displayName(Owner owner) {
144	        if (owner == null) {
145	            return null;
146	        }
147	        return owner.getLastName() + ", " + owner.getFirstName();
148	    }
149	
150	    /**
151	     * Returns the owner's initials as the upper-cased first letters of firstName and
152	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
153	     */
154	    default String initials(Owner owner) {
155	        if (owner == null) {
156	            return null;
157	        }
158	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
159	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
160	    }
161	
162	    Owner toOwner(OwnerDto ownerDto);
163	
164	    @Mapping(target = "id", ignore = true)
165	    @Mapping(target = "pets", ignore = true)
166	    Owner toOwner(OwnerFieldsDto ownerDto);
167	
168	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
169	
170	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
171	
172	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
173	        OwnerPageDto ownerPageDto = new OwnerPageDto();
174	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
175	        ownerPageDto.setPage(ownerPage.getNumber());
176	        ownerPageDto.setSize(ownerPage.getSize());
177	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
178	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
179	        return ownerPageDto;
180	    }
181	}
